'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7', file:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',
  wallet:'M3 6h18v14H3z M3 6V4h15 M15 11h6v5h-6z', calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',
  check:'m5 12 4 4L19 6', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',
  plus:'M12 5v14 M5 12h14', upload:'M12 16V3 m-5 5 5-5 5 5 M4 15v6h16v-6', arrow:'M5 12h14 m-6-6 6 6-6 6',
  mail:'M3 5h18v14H3z m0-14 9 7 9-7', spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',
  trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',
  close:'m6 6 12 12 M18 6 6 18', left:'m15 5-7 7 7 7', right:'m9 5 7 7-7 7', edit:'m4 16 12-12 4 4-12 12H4z',
  download:'M12 3v13 m-5-5 5 5 5-5 M4 17v4h16v-4', info:'M12 8v.1 M12 11v6 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const navItems = [['overview','Übersicht','home'],['documents','Dokumente','file'],['transactions','Buchungen','wallet'],['tasks','Aufgaben','check'],['calendar','Kalender','calendar'],['settings','KI & Einstellungen','settings']];
const kinds = ['Rechnung','Kontoauszug','Finanzamt','Vertrag','Plattformabrechnung','PR-Sample','Privatunterlage','Sonstiges'];
const categories = ['Unsortiert','Plattformerlöse','Partnerschaft','Equipment','Software & Abos','Internet & Telefon','Gebühren','Videoproduktion','Geschäftsessen','Sonstiges'];
const months = ['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
const app = {data:null,year:2025,view:'overview',search:'',kind:'',month:'',taskFilter:'open',calendarYear:new Date().getFullYear(),calendarMonth:new Date().getMonth(),models:[],pendingFile:null,transactionReceiptFile:null,poll:null,analysis:null,analysisDoc:null};
const THEME_KEY='cay-steuerstudio-theme';
function readTheme(){try{const value=window.localStorage?.getItem(THEME_KEY);return value==='dark'||value==='light'?value:'light';}catch{return 'light';}}
function updateThemeButton(theme){const button=$('#theme-toggle');if(!button)return;const dark=theme==='dark';button.setAttribute?.('aria-pressed',String(dark));button.setAttribute?.('aria-label',dark?'Helles Design aktivieren':'Darkmode aktivieren');const iconEl=$('#theme-icon');if(iconEl)iconEl.textContent=dark?'☀':'☾';const label=$('#theme-label');if(label)label.textContent=dark?'Hell':'Dark';}
function applyTheme(theme,persist=true){const value=theme==='dark'?'dark':'light';const root=document.documentElement;if(root?.dataset)root.dataset.theme=value;if(persist){try{window.localStorage?.setItem(THEME_KEY,value);}catch{}}updateThemeButton(value);}
function toggleTheme(){const current=document.documentElement?.dataset?.theme||readTheme();applyTheme(current==='dark'?'light':'dark');toast(current==='dark'?'Helles Design aktiviert.':'Darkmode aktiviert.');}
applyTheme(readTheme(),false);
const money = c => new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(c/100);
const localDate = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const fmtDate = d => d ? new Intl.DateTimeFormat('de-DE').format(new Date(d+'T12:00:00')) : 'Noch offen';
const button = (label,action,ico='',cls='',attrs='') => `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const options = (items,value) => items.map(item=>{const [v,l]=Array.isArray(item)?item:[item,item];return `<option value="${esc(v)}"${String(v)===String(value)?' selected':''}>${esc(l)}</option>`;}).join('');
const field = (label,name,value='',type='text',attrs='') => `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;
const select = (label,name,items,value,attrs='') => `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${attrs}>${options(items,value)}</select></div>`;
const textarea = (label,name,value='',attrs='') => `<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" rows="4" ${attrs}>${esc(value)}</textarea></div>`;
const years = () => Array.from({length:Math.max(2027,new Date().getFullYear()+1,app.year)-2023},(_,i)=>2024+i);
const docsForYear = () => app.data.documents.filter(d=>d.year===app.year);
let txForYear = () => app.data.transactions.filter(t=>t.paid_on.startsWith(String(app.year)));
const tasksForYear = () => app.data.tasks.filter(t=>t.year===app.year);
const totals = tx => tx.reduce((sum,t)=>{sum[t.direction]+=t.amount_cents;return sum;},{income:0,expense:0});
const empty = (title,copy,ico='file',action='') => `<div class="empty">${icon(ico)}<strong>${title}</strong><p>${copy}</p>${action}</div>`;
const head = (title,copy,actions='') => `<div class="page-head"><div><div class="eyebrow">DEIN ARBEITSJAHR ${app.year}</div><h1>${title}</h1><p>${copy}</p></div><div class="head-actions">${actions}</div></div>`;

async function api(path, payload, method='POST') {
  const response=await fetch(path,payload===undefined?{cache:'no-store'}:{method,headers:{'Content-Type':'application/json','X-Cay-Token':$('meta[name="cay-token"]').content},body:JSON.stringify(payload)});
  const value=await response.json();if(!response.ok){const error=new Error(value.error||'Die Anfrage ist fehlgeschlagen.');error.details=value.details;throw error;}return value;
}
async function refresh(){app.data=await api('/api/state');render();}
function toast(message,error=false){clearTimeout(app.toastTimer);const el=$('#toast');el.textContent=message;el.className='toast visible'+(error?' error':'');app.toastTimer=setTimeout(()=>el.className='toast',6500);}
async function download(path,filename){const response=await fetch(path);if(!response.ok){const r=await response.json();throw new Error(r.error||'Download fehlgeschlagen.');}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function navigate(view){app.view=view;app.search='';app.kind='';location.hash=view;render();}
function render(){
  if(!app.data)return;
  const secondary=new Set(['taxyear','calendar','assessments','knowledge','safety','settings']);
  const navLink=([id,label,ico])=>`<a class="nav-item${app.view===id?' active':''}" href="#${id}" data-action="navigate" data-view="${id}" aria-label="${label}"${app.view===id?' aria-current="page"':''}>${icon(ico)}<span class="nav-label">${label}</span></a>`;
  $('#nav').innerHTML=navItems.filter(n=>!secondary.has(n[0])&&!['transactions','banking'].includes(n[0])).map(navLink).join('')+`<details class="nav-more"${secondary.has(app.view)?' open':''}><summary aria-label="Weitere Bereiche">${icon('settings')}<span>Mehr</span></summary><div class="nav-more-links">${navItems.filter(n=>secondary.has(n[0])).map(navLink).join('')}</div></details>`;
  $('#breadcrumb-current').textContent=navItems.find(n=>n[0]===app.view)[1];
  $('#year-select').innerHTML=options(years(),app.year);
  $('#main').innerHTML=({overview:overviewView,documents:documentsView,transactions:transactionsView,tasks:tasksView,calendar:calendarView,settings:settingsView}[app.view])();
  const drop=$('#dropzone');if(drop){drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files.length!==1)return toast('Bitte eine Datei pro Vorgang ablegen.',true);documentForm(null,e.dataTransfer.files[0]);});}
}
function stat(label,value,copy,ico){return `<section class="stat-card"><div class="stat-top">${label}<span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${copy}</div></section>`;}
function overviewView(){
  const docs=docsForYear(),tx=txForYear(),sum=totals(tx),tasks=tasksForYear().filter(t=>t.status!=='done').sort((a,b)=>(a.due_on||'9999').localeCompare(b.due_on||'9999'));
  return head('Alles an einem Ort.','Belege sammeln. Vorgänge ordnen. Den Überblick behalten.',button('Buchung erfassen','new-transaction','plus')+button('Dokument hinzufügen','new-document','upload','primary'))+
  `<div class="stat-grid">${stat('Einnahmen',money(sum.income),'Erfasste Zahlungen · keine EÜR','wallet')}${stat('Ausgaben',money(sum.expense),'Erfasste Zahlungen · keine Abzugsprüfung','wallet')}${stat('Dokumente',docs.length,'Originale & manuelle Unterlagen','file')}${stat('Offene Aufgaben',tasks.length,'Für dein ausgewähltes Arbeitsjahr','calendar')}</div>
  ${app.data.settings.vat_status==='unknown'||app.data.settings.filing_2025==='unknown'?`<div class="banner">${icon('info')}<div class="banner-text"><strong>Einmal klären, sicher weiterarbeiten.</strong><br>Umsatzsteuerstatus und Bearbeitungsstand 2025 sind noch offen. Du kannst deine Unterlagen bereits erfassen.</div><button class="text-link" data-action="startcheck">Startcheck öffnen</button></div>`:''}
  <div class="content-grid"><div class="stack"><section class="panel"><div class="panel-header"><h2>Dein nächster Beleg</h2><span class="tag">Lokal gespeichert</span></div><div class="panel-body"><button class="dropzone" id="dropzone" data-action="new-document"><span class="upload-symbol">${icon('upload')}</span><strong>Dokument hier ablegen</strong><p>oder anklicken und eine Datei auswählen</p><span class="file-types">PDF, JPG, PNG, TXT, CSV, XML · bis 20 MB</span></button><div class="quick-row">${button('Finanzamtspost','new-letter','mail')}${button('Vertrag oder PR-Sample','new-contract','file')}</div></div></section>
  <section class="panel"><div class="panel-header"><h2>Zuletzt erfasst</h2><button class="text-link" data-action="show-transactions">Alle Buchungen</button></div>${tx.length?transactionTable(tx.slice(0,5)):empty('Hier beginnt dein Überblick.','Erfasse eine erste Einnahme oder Ausgabe und ordne den passenden Beleg zu.','wallet')}</section></div>
  <div class="stack"><section class="panel"><div class="panel-header"><h2>Als Nächstes</h2><span class="tag">${tasks.length} offen</span></div><div class="panel-body">${tasks.length?tasks.slice(0,4).map(taskRow).join(''):empty('Noch keine offenen Aufgaben','Ein Brief mit Handlungsbedarf? Lege eine Aufgabe mit geprüfter Frist an.','check')}${button('Aufgabe hinzufügen','new-task','plus','ghost small')}</div></section>
  <section class="panel"><div class="panel-header"><h2>Dein Start ab 2025</h2></div><div class="panel-body"><ol class="setup-list">${setupItem(1,'Unterlagen einsammeln','Belege, Briefe, Verträge und private Nachweise getrennt ablegen.','new-document')}${setupItem(2,'Zahlungen zuordnen','Betrag und Zahlungsdatum mit dem Kontoauszug abgleichen.','new-transaction')}${setupItem(3,'Offene Punkte klären','Status 2025, Fristen und Übernahmen aus 2024.','startcheck')}</ol></div></section></div></div>`;
}
function setupItem(n,title,copy,action){return `<li class="setup-item"><span class="setup-number">${n}</span><div><strong>${title}</strong><p>${copy}</p><button class="text-link" data-action="${action}">Öffnen</button></div></li>`;}
function transactionEvidence(t){const ids=t.document_ids||[],scope=t.scope||'business';if(ids.length)return `<span class="tag green">${ids.length} zugeordnet</span>`;if(scope==='private')return '<span class="tag">Privat · kein Betriebsbeleg</span>';if(scope==='transfer')return '<span class="tag green">Eigenübertrag · neutral</span>';if(scope==='unknown')return '<span class="tag amber">Bereich prüfen</span>';if(t.receipt_state==='none')return '<span class="tag amber">Kein Beleg angegeben · Prüfung offen</span>';return '<span class="tag amber">Beleg fehlt</span>';}
function transactionTable(tx){return `<div class="table-wrap"><table><thead><tr><th>Vorgang</th><th>Zahlungsdatum</th><th>Beleg</th><th>Betrag</th></tr></thead><tbody>${tx.map(t=>`<tr><td><button class="table-button" data-action="edit-transaction" data-id="${t.id}">${esc(t.partner)}</button><div class="cell-secondary">${esc(t.title)}${t.payment_method==='cash'?' · Bar bezahlt':''}</div></td><td class="mono">${fmtDate(t.paid_on)}</td><td>${transactionEvidence(t)}</td><td class="amount ${t.direction==='income'?'positive':''}">${t.direction==='income'?'+':'−'} ${money(t.amount_cents)}</td></tr>`).join('')}</tbody></table></div>`;}
function searchInput(){return `<label class="search-wrap"><span class="sr-only">Suchen</span><input type="search" id="search" placeholder="Suchen …" value="${esc(app.search)}"></label>`;}
function documentsView(){const docs=docsForYear().filter(d=>(app.kind?d.kind===app.kind:d.kind!=='Kontoauszug')&&`${d.title} ${d.partner} ${d.filename} ${d.notes}`.toLowerCase().includes(app.search.toLowerCase())).sort((a,b)=>(b.document_date||b.created_at).localeCompare(a.document_date||a.created_at));
  return head('Deine Unterlagen.','Rechnungen, Briefe und Verträge an einem Ort.',button('Dokument hinzufügen','new-document','plus','primary'))+
  `<div class="document-links">${button('Kontoauszüge findest du bei Zahlungen','navigate','wallet','ghost small','data-view="banking"')}${button('Papierkorb','open-trash','trash', 'ghost small')}</div><div class="toolbar"><div class="toolbar-left">${searchInput()}<select id="kind-filter" aria-label="Dokumentart">${options([['','Belege, Briefe & Verträge'],...kinds],app.kind)}</select></div><span class="muted small">${docs.length} Dokumente</span></div>`+
  (docs.length?`<div class="doc-grid">${docs.map(d=>`<button class="doc-card" data-action="open-document" data-id="${d.id}"><span class="doc-card-top"><span class="document-type-icon">${icon(d.kind==='Finanzamt'?'mail':'file')}</span><span class="tag ${d.kind==='PR-Sample'?'amber':d.kind==='Finanzamt'?'blue':''}">${esc(d.kind)}</span></span><span><strong>${esc(d.title)}</strong><span class="doc-description">${esc(d.partner||d.filename||'Manueller Text')}</span></span><span class="doc-card-bottom"><span>${d.document_date?fmtDate(d.document_date):'Datum noch offen'}</span><span>${d.body?'Text vorhanden':'Text ergänzen'}</span></span></button>`).join('')}</div>`:empty('Platz für deine Unterlagen.','Lade ein Original hoch oder erfasse den Dokumenttext manuell.','file',button('Erstes Dokument','new-document','plus','primary')));
}
function transactionsView(){const tx=txForYear().filter(t=>(!app.month||t.paid_on.slice(5,7)===app.month)&&`${t.partner} ${t.title} ${t.category}`.toLowerCase().includes(app.search.toLowerCase())),sum=totals(tx);
  return head('Deine Buchungen.','Betriebliche und private Zahlungen getrennt prüfen. Bei privaten Bewegungen genügt das Zahlungsdatum.',button('CSV herunterladen','export','download')+button('Buchung erfassen','new-transaction','plus','primary'))+
  `<div class="toolbar"><div class="toolbar-left">${searchInput()}<select id="month-filter" aria-label="Monat">${options([['','Alle Monate'],...months.map((m,i)=>[String(i+1).padStart(2,'0'),m])],app.month)}</select></div><span class="tag">${tx.length} Buchungen</span></div><div class="payment-summary"><span>Einnahmen <strong>${money(sum.income)}</strong></span><span>Ausgaben <strong>${money(sum.expense)}</strong></span><span>Zahlungssaldo <strong>${money(sum.income-sum.expense)}</strong></span></div><section class="panel">${tx.length?transactionTable(tx):empty('Noch keine Buchungen in dieser Auswahl.','Betrag, Empfänger und Zahlungsdatum genügen für den Anfang.','wallet')}<div class="table-footer">Zahlungsübersicht, kein steuerlicher Gewinn. PR-Samples ohne Geldzahlung separat als Dokument erfassen.</div></section>`;
}
function taskRow(t){const overdue=t.due_on&&t.due_on<localDate()&&t.status!=='done';return `<div class="task-row"><span class="task-marker${overdue?' overdue':''}"></span><div class="task-row-main"><button class="table-button" data-action="edit-task" data-id="${t.id}">${esc(t.title)}</button><p>${esc(t.kind)} · ${t.status==='done'?'Erledigt':t.due_confirmed?'Frist bestätigt':'Frist prüfen'}</p>${t.prepare_on?`<p>Vorbereiten bis ${fmtDate(t.prepare_on)}</p>`:''}</div><span class="task-date${overdue?' overdue':''}">${fmtDate(t.due_on)}</span></div>`;}
function tasksView(){const tasks=tasksForYear().filter(t=>app.taskFilter==='all'||(app.taskFilter==='done'?t.status==='done':t.status!=='done'));
  return head('Ein Schritt nach dem anderen.','Fristen prüfen, rechtzeitig vorbereiten und Nachweise festhalten.',button('Aufgabe hinzufügen','new-task','plus','primary'))+
  `<div class="toolbar"><select id="task-filter" aria-label="Aufgabenstatus">${options([['open','Offene Aufgaben'],['done','Erledigte Aufgaben'],['all','Alle Aufgaben']],app.taskFilter)}</select></div><section class="panel"><div class="panel-body">${tasks.length?tasks.map(taskRow).join(''):empty('Alles übersichtlich.','Lege eine Aufgabe an, sobald ein Brief oder Vertrag eine Handlung erfordert.','check')}</div></section>`;
}
function calendarView(){const year=app.calendarYear,first=new Date(year,app.calendarMonth,1),offset=(first.getDay()+6)%7,tasks=tasksForYear();let cells='';
  for(let i=0;i<42;i++){const date=new Date(year,app.calendarMonth,i-offset+1),iso=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;cells+=`<div class="calendar-day${date.getMonth()!==app.calendarMonth?' other':''}${iso===localDate()?' today':''}"><span class="day-number">${date.getDate()}</span>${tasks.filter(t=>t.due_on===iso||t.prepare_on===iso).map(t=>`<button class="event${!t.due_confirmed?' unconfirmed':''}${t.status==='done'?' done':''}" data-action="edit-task" data-id="${t.id}" title="${esc(t.title)}">${t.prepare_on===iso?'Vorbereiten: ':''}${esc(t.title)}</button>`).join('')}</div>`;}
  const current=tasks.filter(t=>[t.due_on,t.prepare_on].some(d=>d.startsWith(`${year}-${String(app.calendarMonth+1).padStart(2,'0')}`)));
  return head('Dein Kalender.',`Termine zum Arbeitsjahr ${app.year}, auch in Folgejahren. Blau: bestätigt.`,button('Kalender exportieren','calendar-export','download')+button('Aufgabe hinzufügen','new-task','plus','primary'))+
  `<div class="calendar-layout"><section class="panel"><div class="panel-header"><div class="calendar-controls"><button class="icon-btn" data-action="prev-month" aria-label="Voriger Monat">${icon('left')}</button><h2>${months[app.calendarMonth]} ${year}</h2><button class="icon-btn" data-action="next-month" aria-label="Nächster Monat">${icon('right')}</button></div></div><div class="calendar-grid">${['MO','DI','MI','DO','FR','SA','SO'].map(d=>`<div class="weekday">${d}</div>`).join('')}${cells}</div></section><section class="panel calendar-agenda"><div class="panel-header"><h2>In diesem Monat</h2></div><div class="panel-body">${current.length?current.map(taskRow).join(''):empty('Keine Termine','Für diesen Monat ist noch nichts eingetragen.','calendar')}</div></section></div><p class="page-note">Bernsteinfarbene Termine sind noch zu prüfen. Der Export enthält nur bestätigte Fristen. Datei in deinen Kalender importieren und Erinnerungen dort prüfen. Keine automatische Synchronisierung; Änderungen und entfernte Termine im Kalender kontrollieren.</p>`;
}
function taxProfilePanel(){const s=app.data.settings,p=(app.data.tax_profiles||[]).find(p=>p.year===app.year)||{vat_status:'unknown',taxation:'unknown',filing_status:'unknown',source_note:''},proposal=app.data.tax_profile_proposal;
 const legacy=!p.updated_at&&((s.vat_status&&s.vat_status!=='unknown')||(s.taxation&&s.taxation!=='unknown'));
 return `<section class="panel"><div class="panel-header"><h2>Steuerlicher Ausgangspunkt</h2><span class="tag">${app.year}</span></div><div class="panel-body"><p class="small muted">Diese Auswahl gilt nur für ${app.year}. Das Arbeitsjahr wechselst du oben.</p>
 ${proposal&&app.year===proposal.year?`<div class="profile-hint"><strong>Aus deinen Bescheiden 2024</strong><p>Regelbesteuerung und abgegebene Erklärungen sind belegt. Die Einkommensteuerprüfung bleibt offen. Ist-/Soll-Versteuerung ist nicht belegt.</p><div class="actions">${button('2024-Angaben einsetzen','profile-proposal','','small')}${button('Bescheide ansehen','navigate','','small','data-view="assessments"')}</div></div>`:app.year===2024?`<p class="small">Deine vorbereiteten Bescheide kannst du unter <button class="text-link" data-action="navigate" data-view="assessments">Bescheide</button> übernehmen. Danach erscheint hier ein Vorschlag für 2024.</p>`:''}
 ${legacy?`<details class="profile-help"><summary>Bisherige Angaben ohne Jahreszuordnung</summary><p>Gespeichert waren: ${esc({unknown:'Ungeklärt',small:'Kleinunternehmer',regular:'Regelbesteuerung'}[s.vat_status]||'Ungeklärt')} · ${esc({unknown:'Ungeklärt',cash:'Ist-Versteuerung',accrual:'Soll-Versteuerung'}[s.taxation]||'Ungeklärt')}. Sie bleiben erhalten. Übernimm sie nur für ein belegtes Jahr.</p></details>`:''}
 <form id="profile-form" data-year="${app.year}"><input type="hidden" name="year" value="${app.year}">
 ${select('Umsatzsteuerstatus '+app.year,'vat_status',[['unknown','Noch zu klären'],['small','Kleinunternehmer'],['regular','Regelbesteuerung']],p.vat_status)}
 ${select('Umsatzsteuer: Ist oder Soll?','taxation',[['unknown','Noch zu klären'],['cash','Ist-Versteuerung'],['accrual','Soll-Versteuerung']],p.taxation)}
 ${select('Steuererklärungen '+app.year,'filing_status',[['unknown','Bearbeitungsstand unbekannt'],['open','Noch offen'],['submitted','Abgegeben – Nachweise vorhanden']],p.filing_status)}
 <details class="profile-help"><summary>Was soll ich auswählen?</summary><p><strong>Umsatzsteuerstatus:</strong> Jahreserklärung oder Finanzamtsunterlagen prüfen. Die Bescheide 2024 beantworten nicht automatisch den Status 2025.</p><p><strong>Ist/Soll:</strong> Unterlagen zur Gestattung durch das Finanzamt oder Angaben zur Berechnungsart in der eingereichten USt-Erklärung prüfen. Eine EÜR allein beantwortet das nicht. <a href="https://www.gesetze-im-internet.de/ustg_1980/__20.html" target="_blank" rel="noreferrer">§ 20 UStG ↗</a></p><p><strong>Abgabestand:</strong> „Noch offen“, wenn noch nicht eingereicht; „Abgegeben“ nur mit passenden Nachweisen. Teilweise abgegebene Erklärungen unten einzeln notieren. Abgegeben heißt nicht inhaltlich geprüft.</p><p>Wenn du es nicht weißt, lass „Noch zu klären“ stehen. Belege kannst du trotzdem erfassen.</p></details>
 ${textarea('Nachweis / offene Frage für '+app.year,'source_note',p.source_note,'maxlength="2000" placeholder="Zum Beispiel: USt-Erklärung 2025 liegt noch nicht vor …"')}
 ${textarea('Dauerhafte Notizen · alle Jahre','personal_notes',s.personal_notes,'maxlength="10000" placeholder="Angaben mit Jahr nennen, z. B. Student und BAföG im Jahr …"')}
 <p class="small muted settings-note">Gespeicherte Angaben und ein Auszug deiner Notizen werden der KI mitgegeben. Sie ersetzen keine Prüfung der Originalunterlagen.</p><button class="btn primary" type="submit">Angaben für ${app.year} speichern</button><div class="form-result" role="status"></div></form></div></section>`;
}
function settingsView(){const s=app.data.settings;return head('Dein Steuerstudio.','Gesicherte Fakten, lokale KI und deine nächsten Schritte.')+
  `<div class="settings-grid">${taxProfilePanel()}
  <section class="panel"><div class="panel-header"><h2>Deine lokale KI</h2><span class="tag">Ollama</span></div><div class="panel-body"><p class="settings-intro">Zwei Leser werten denselben Dokumenttext getrennt aus. Du prüfst Vorschläge vor der Übernahme.</p>${button('Verbindung prüfen & Modelle laden','check-models','spark')}<p id="model-status" class="model-status">Ein laufendes Ollama und ein installiertes lokales Modell sind erforderlich.</p><form id="ai-form">${select('Erster Leser','worker_model',[['','Modell auswählen'],...new Set([s.worker_model,...app.models].filter(Boolean))],s.worker_model)}${select('Zweiter Leser','reviewer_model',[['','Modell auswählen'],...new Set([s.reviewer_model,...app.models].filter(Boolean))],s.reviewer_model)}<button class="btn primary" type="submit">Modelle speichern</button><div class="form-result" role="status"></div></form><div class="divider"></div><p class="small muted">Keine kostenpflichtige API angebunden. Keine Rechtsrecherche oder automatische Steuerfreigabe. Dasselbe Modell in beiden Rollen ist keine unabhängige fachliche Kontrolle.</p></div></section>
  <details class="panel wide-note settings-section"><summary>Vor der Abgabe prüfen <span class="tag amber">Startcheck</span></summary><div class="panel-body"><div class="checklist-grid"><div><h3>2025 & Übergang aus 2024</h3><p>Welche Erklärungen und Voranmeldungen wurden schon abgegeben? Vorhandene Protokolle, Bescheide und offene Einsprüche sichern. Anlagenverzeichnis und fortgeführte Werte aus 2024 übernehmen – nicht erneut buchen.</p></div><div><h3>Privat bleibt getrennt</h3><p>Lohnsteuerbescheinigungen, Studien- und BAföG-Unterlagen als „Privatunterlage“ ablegen. Die Zahlungsübersicht ist für betriebliche Vorgänge; sie berechnet noch keine private Einkommensteuer.</p></div><div><h3>PR-Samples & Plattformen</h3><p>Sachvergütung als „PR-Sample“ dokumentieren: Produkt, Anbieter, Erhalt, Wertnachweis, Nutzung und Rückgabe. Keine erfundene Geldzahlung. Bei Plattformen Vertragspartner, Abrechnung, Gebühren und Währung sammeln.</p></div><div><h3>Monatlich abschließen</h3><p>Bank und gegebenenfalls PayPal mit den Buchungen abgleichen. Fehlende Belege und ungeklärte Vorgänge als Aufgaben erfassen. Originale, aktuelle Sicherung und Versandnachweise behalten.</p></div></div></div></details>
  <section class="panel wide-note"><div class="panel-header"><h2>Deine Daten gehören dir.</h2>${button('Sicherung herunterladen','backup','download')}</div><div class="panel-body"><p class="small muted">SQLite-Datenbank und Originaldateien liegen im Ordner „daten“. Die ZIP-Sicherung enthält beides und ist nicht verschlüsselt. Auf einem geschützten Datenträger aufbewahren. Noch nicht enthalten: Bankabgleich per Import, Bild-OCR, Steuerberechnung, ELSTER und ein Hintergrund-Erinnerungsdienst.</p></div></section></div>`;}

function showModal(title,body){clearTimeout(app.poll);$('#modal-content').innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Schließen">${icon('close')}</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){clearTimeout(app.poll);$('#modal').close();app.pendingFile=null;app.transactionReceiptFile=null;app.analysisDoc=null;}
function formButtons(id,entity){return `<div class="modal-footer">${id?button(entity==='documents'?'In Papierkorb':'Archivieren','archive','','ghost danger small left',`data-id="${id}" data-entity="${entity}"`):''}${button('Abbrechen','close-modal')}<button type="submit" class="btn primary">Speichern</button></div>`;}
function documentForm(id=null,file=null,kind='Rechnung'){
  const d=app.data.documents.find(x=>x.id===id)||{};app.pendingFile=file;
  showModal(id?'Dokument bearbeiten':'Dokument hinzufügen',`<form id="document-form" data-id="${id||''}"><div class="modal-body"><div class="form-result" role="alert"></div>${!id?`<div class="file-picker"><label for="document-file">Originaldatei</label><input id="document-file" type="file" accept=".pdf,.jpg,.jpeg,.png,.txt,.csv,.xml"><p id="file-label">${file?esc(file.name):'Bis 20 MB. Alternativ unten den vollständigen Dokumenttext eingeben.'}</p></div>`:`<p class="small muted settings-note">Die Originaldatei bleibt unverändert. Änderungen an Text oder Datumsangaben machen zugehörige Fristen erneut prüfpflichtig.</p>`}
  ${field('Titel','title',d.title||file?.name||'','text','required maxlength="200"')}<div class="field-row">${select('Dokumentart','kind',kinds,d.kind||kind)}${select('Arbeitsjahr','year',years(),d.year||app.year)}</div><div class="field-row">${field('Dokumentdatum','document_date',d.document_date,'date')}${field('Erhalten am','received_date',d.received_date,'date')}</div>${field('Absender / Geschäftspartner','partner',d.partner,'text','maxlength="200"')}${textarea('Notizen und offene Fragen','notes',d.notes,'maxlength="10000" placeholder="Bei PR-Samples: Produkt, Wertnachweis, Erhalt, Nutzung und Rückgabe …"')}${textarea('Vollständiger Dokumenttext für die KI','body',d.body,'maxlength="100000"')}<p class="small muted">Lesbare PDFs benötigen die optionale PDF-Unterstützung. Fotos und Scans werden gespeichert. Für gescannte Kontoauszüge den Bereich Kontoauszüge mit lokaler OCR nutzen; bei anderen Bilddokumenten Text ergänzen. „Erhalten am“ ist keine berechnete rechtliche Bekanntgabe.</p></div>${formButtons(id,'documents')}</form>`);
}
function transactionForm(id=null){const t=app.data.transactions.find(x=>x.id===id)||{};
  showModal(id?'Buchung bearbeiten':'Buchung erfassen',`<form id="transaction-form" data-id="${id||''}"><div class="modal-body"><div class="form-result" role="alert"></div><div class="field-row">${select('Art','direction',[['expense','Ausgabe'],['income','Einnahme']],t.direction||'expense')}${field('Betrag in Euro','amount',t.amount_cents?`${Math.floor(t.amount_cents/100)},${String(t.amount_cents%100).padStart(2,'0')}`:'','text','required inputmode="decimal" placeholder="49,90"')}</div><div class="field-row">${field('Bezahlt am','paid_on',t.paid_on||'','date','required')}${field('Rechnungsdatum','invoice_date',t.invoice_date,'date')}</div>${field('Empfänger / Absender','partner',t.partner,'text','required maxlength="200"')}${field('Beschreibung','title',t.title,'text','required maxlength="200"')}${select('Vorläufige Kategorie','category',categories,t.category||'Unsortiert')}<div class="file-picker receipt-picker"><label for="transaction-receipt-file">Rechnung / Beleg (optional)</label><input id="transaction-receipt-file" type="file" accept=".pdf,.jpg,.jpeg,.png,.txt,.csv,.xml"><p id="transaction-receipt-label" class="small muted">Originalrechnung direkt mit dieser Buchung speichern.</p></div>
  <details class="document-link-details"><summary>Bereits vorhandenen Beleg verknüpfen (optional)</summary><div class="field"><label for="f-document_ids">Passende Belege (Mehrfachauswahl möglich)</label><select name="document_ids" id="f-document_ids" multiple size="4">${app.data.documents.map(d=>`<option value="${d.id}"${(t.document_ids||[]).includes(d.id)?' selected':''}>${d.year} · ${esc(d.title)}</option>`).join('')}</select><span class="help">Für betriebliche oder gemischte Vorgänge den Beleg zuordnen. Bei einer privaten Zahlung oder einem Eigenübertrag ist kein separater Betriebsbeleg erforderlich.</span></div></details>${textarea('Notizen','notes',t.notes,'maxlength="10000"')}<label class="check"><input type="checkbox" name="data_checked"${t.data_checked?' checked':''}><span class="data-checked-label">Betrag, Zahlungsdatum und Beleg am Original geprüft. Das bestätigt noch keine steuerliche Absetzbarkeit.</span></label><p class="small muted">Tatsächliche Zahlungen in Euro erfassen und den Bereich korrekt zuordnen. PR-Samples ohne Zahlung als Dokument erfassen. Anteile und Umsatzsteuerangaben sind noch keine steuerliche Freigabe.</p></div>${formButtons(id,'transactions')}</form>`);
}
function taskForm(id=null,preset={}){const t=app.data.tasks.find(x=>x.id===id)||preset;
  showModal(id?'Aufgabe bearbeiten':'Aufgabe hinzufügen',`<form id="task-form" data-id="${id||''}"><div class="modal-body"><div class="form-result" role="alert"></div>${field('Was ist zu tun?','title',t.title,'text','required maxlength="200"')}<div class="field-row">${select('Aufgabenart','kind',['Unterlagen','Antwort','Abgabe','Zahlung','Vertrag','Sonstiges'],t.kind||'Unterlagen')}${select('Arbeitsjahr','year',years(),t.year||app.year)}</div><div class="field-row">${field('Äußere Frist','due_on',t.due_on,'date')}${field('Vorbereiten bis','prepare_on',t.prepare_on,'date')}</div><label class="check"><input name="due_confirmed" type="checkbox"${t.due_confirmed?' checked':''}>Ich habe dieses Fristdatum anhand des Originals und der maßgeblichen Angaben geprüft. Erst dann darf es exportiert werden.</label>${select('Quelldokument','source_id',[['','Ohne verknüpftes Dokument'],...app.data.documents.map(d=>[d.id,`${d.year} · ${d.title}`])],t.source_id||'')}${textarea('Fundstelle / Begründung der Frist','source_quote',t.source_quote,'maxlength="3000"')}${textarea('Notizen','notes',t.notes,'maxlength="10000"')}${select('Status','status',[['open','Offen'],['working','In Bearbeitung'],['done','Erledigt']],t.status||'open')}${textarea('Versand- oder Zahlungsnachweis','proof',t.proof,'maxlength="2000" placeholder="Protokollnummer, Datum und Ablageort des Nachweises …"')}<p class="small muted">Für erledigte Antworten, Abgaben und Zahlungen ist eine Nachweisangabe erforderlich. Es werden keine gesetzlichen Fristen automatisch berechnet.</p></div>${formButtons(id,'tasks')}</form>`);
}
async function documentDetail(id){const d=app.data.documents.find(x=>x.id===id);if(!d)return;
  showModal(esc(d.title),`<div class="modal-body"><div class="detail-meta"><span class="tag">${esc(d.kind)}</span><span class="tag">${d.year}</span><span class="tag">${fmtDate(d.document_date)}</span></div><div class="actions">${d.stored_name?button('Original herunterladen','original','download','',`data-id="${id}"`):''}${button('Bearbeiten','edit-document','edit','',`data-id="${id}"`)}${button('In Papierkorb','trash-upload','', 'ghost',`data-document-id="${id}"`)}${d.kind==='Kontoauszug'&&d.stored_name&&/\.pdf$/i.test(d.filename)?button('Zahlungen einlesen','read-statement-document','wallet','',`data-id="${id}"`):''}${button('Aufgabe anlegen','task-from-document','plus','',`data-id="${id}"`)}</div>${d.notes?`<h3 class="section-label">Deine Notizen</h3><p class="document-text">${esc(d.notes)}</p>`:''}<h3 class="section-label">Dokumenttext</h3><p class="document-text">${esc(d.body||'Noch kein lesbarer Text vorhanden. Du kannst ihn unter „Bearbeiten“ ergänzen.')}</p><p class="small muted extraction-note">${esc(d.extraction_note)}</p><div class="ai-area"><div class="modal-subnav"><h3>KI-Lesehilfe</h3>${button('Dokument auswerten','analyze','spark','primary small',`data-id="${id}"`)}</div><div id="analysis-content">Bisherige Auswertungen werden geladen …</div></div></div>`);
  app.analysisDoc=id;app.analysis=null;await loadAnalysis(id);
}
async function loadAnalysis(id){try{const items=await api(`/api/documents/${id}/analyses`);if(app.analysisDoc!==id||!$('#analysis-content'))return;app.analysis=items[0]||null;$('#analysis-content').innerHTML=analysisView(app.analysis);const running=app.analysis&&['queued','running'].includes(app.analysis.state);$('[data-action="analyze"]').disabled=!!running;if(running)app.poll=setTimeout(()=>loadAnalysis(id),2500);}catch(e){if($('#analysis-content'))$('#analysis-content').textContent=e.message;}}
function analysisView(a){if(!a)return '<p class="small muted">Noch keine Auswertung. Die lokale KI schlägt Angaben vor; sie bucht und übermittelt nichts.</p>';if(['running','queued'].includes(a.state))return '<p class="progress-label"><span class="spinner"></span>Zwei Leser prüfen den Text nacheinander. Das kann einige Minuten dauern.</p>';if(a.state==='error')return `<div class="form-error">${esc(a.error)}</div>`;if(a.state==='outdated')return '<div class="form-error">Die Quelle wurde geändert. Bitte erneut auswerten; frühere Vorschläge sind nicht mehr aktuell.</div>';
  return `${a.worker_model===a.reviewer_model?'<p class="small muted">Beide Leser verwenden dasselbe Modell. Das ist keine unabhängige fachliche Freigabe.</p>':''}${reading(a.worker_json,0,a.worker_model)}${reading(a.reviewer_json,1,a.reviewer_model)}<p class="small muted extraction-note">„Zitat gefunden“ prüft nur das Vorkommen des Textes. Es bestätigt weder die Deutung noch das Fristdatum. Beide Ergebnisse können denselben Fehler enthalten.</p>`;}
function reading(r,pass,model){if(!r)return '';return `<section class="ai-reading"><h3>${pass?'Zweiter':'Erster'} Leser · ${esc(model)}</h3><p>${esc(r.summary)}</p>${(r.facts||[]).map(f=>`<div class="fact"><strong>${esc(f.label)}</strong><p>${esc(f.value)}</p><div class="quote">${esc(f.quote)}</div><span class="tag ${f.source_found?'blue':'amber'}">${f.source_found?'Zitat gefunden':'Quelle prüfen'}</span></div>`).join('')}${(r.deadlines||[]).map((f,i)=>`<div class="fact"><strong>${esc(f.title)} · ${fmtDate(f.date)}</strong><div class="quote">${esc(f.quote)}</div><span class="tag ${f.source_found?'blue':'amber'}">${f.source_found?'Zitat gefunden · Frist prüfen':'Quelle prüfen'}</span><div class="actions deadline-actions">${button('Als Aufgabe prüfen','task-from-analysis','plus','small',`data-pass="${pass}" data-index="${i}"`)}</div></div>`).join('')}${r.questions?.length?`<h3 class="section-label">Offene Fragen</h3><ul class="ai-questions">${r.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul>`:''}</section>`;}

async function action(name,el){const id=el.dataset.id;
  switch(name){
    case 'navigate':return navigate(el.dataset.view);
    case 'startcheck':return navigate('settings');
    case 'show-transactions':return navigate('transactions');
    case 'new-document':return documentForm();
    case 'new-letter':return documentForm(null,null,'Finanzamt');
    case 'new-contract':return documentForm(null,null,'Vertrag');
    case 'edit-document':return documentForm(id);
    case 'open-document':return documentDetail(id);
    case 'new-transaction':return transactionForm();
    case 'edit-transaction':return transactionForm(id);
    case 'new-task':return taskForm();
    case 'edit-task':return taskForm(id);
    case 'close-modal':return closeModal();
    case 'toggle-theme':return toggleTheme();
    case 'backup':await download('/api/backup',`Cay-Steuerstudio-Sicherung-${localDate()}.zip`);return toast('Sicherung heruntergeladen. Bitte geschützt aufbewahren.');
    case 'export':return download(`/api/export.csv?year=${app.year}`,`Buchungen-${app.year}.csv`);
    case 'calendar-export':return download(`/api/calendar.ics?year=${app.year}`,`Fristen-${app.year}.ics`);
    case 'original':{const d=app.data.documents.find(x=>x.id===id);return download(`/api/documents/${id}/file`,d.filename);}
    case 'prev-month':case 'next-month':{const next=new Date(app.calendarYear,app.calendarMonth+(name==='next-month'?1:-1),1);if(next.getFullYear()<2024||next.getFullYear()>2100)return;app.calendarYear=next.getFullYear();app.calendarMonth=next.getMonth();return render();}
    case 'archive':if(!confirm('Eintrag archivieren? Er verschwindet aus der Arbeitsansicht, bleibt aber in der Sicherung erhalten.'))return;await api(`/api/${el.dataset.entity}/${id}/archive`,{});closeModal();await refresh();return toast('Eintrag archiviert.');
    case 'task-from-document':{const d=app.data.documents.find(x=>x.id===id);return taskForm(null,{source_id:id,year:d.year,title:'Prüfen: '+d.title});}
    case 'analyze':el.disabled=true;try{await api(`/api/documents/${id}/analyze`,{});await loadAnalysis(id);}catch(e){el.disabled=false;throw e;}return;
    case 'task-from-analysis':{const a=app.analysis;if(!a||a.state!=='complete')return;const r=Number(el.dataset.pass)?a.reviewer_json:a.worker_json,f=r.deadlines[Number(el.dataset.index)],d=app.data.documents.find(x=>x.id===app.analysisDoc);return taskForm(null,{title:f.title,source_id:d.id,year:d.year,source_quote:f.quote,due_on:f.source_found?f.date:'',due_confirmed:false,notes:'KI-Vorschlag. Inhalt und Datum am Original prüfen.'});}
    case 'check-models':{el.disabled=true;try{const r=await api('/api/models');app.models=r.models;for(const name of ['worker_model','reviewer_model']){const current=$(`[name="${name}"]`).value;$(`[name="${name}"]`).innerHTML=options([['',name==='reviewer_model'?'Gleiches Modell wie erster Leser':'Modell auswählen'],...new Set([current,...r.models].filter(Boolean))],current);}$('#model-status').textContent=r.models.length?`${r.models.length} lokale Modelle gefunden.`:'Ollama läuft, aber es wurde kein installiertes lokales Modell gefunden.';}catch(e){$('#model-status').textContent=e.message;}finally{el.disabled=false;}return;}
  }
}
function fileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Datei konnte nicht gelesen werden.'));reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.readAsDataURL(file);});}
async function submit(form){const data=Object.fromEntries(new FormData(form)),id=form.dataset.id,submitButton=$('[type="submit"]',form),result=$('.form-result',form);submitButton.disabled=true;result.textContent='';result.className='form-result';
  try{
    if(form.id==='document-form'){data.year=Number(data.year);if(app.pendingFile){if(app.pendingFile.size>20*1024*1024)throw new Error('Bitte eine Datei bis 20 MB auswählen.');data.filename=app.pendingFile.name;data.file_base64=await fileBase64(app.pendingFile);}const r=await api('/api/documents'+(id?'/'+id:''),data,id?'PUT':'POST');closeModal();await refresh();toast(r.duplicate?'Diese Datei ist bereits vorhanden.':'Dokument gespeichert.');await documentDetail(r.id);}
    else if(form.id==='transaction-form'){data.document_ids=[...$('[name="document_ids"]',form).selectedOptions].map(o=>o.value);data.data_checked=$('[name="data_checked"]',form).checked;await api('/api/transactions'+(id?'/'+id:''),data,id?'PUT':'POST');closeModal();await refresh();toast('Buchung gespeichert.');}
    else if(form.id==='task-form'){data.year=Number(data.year);data.due_confirmed=$('[name="due_confirmed"]',form).checked;await api('/api/tasks'+(id?'/'+id:''),data,id?'PUT':'POST');closeModal();await refresh();toast('Aufgabe gespeichert.');}
    else {await api('/api/settings',data);await refresh();toast('Einstellungen gespeichert.');}
  }catch(e){result.className='form-result form-error';result.textContent=e.message;}finally{submitButton.disabled=false;}
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();Promise.resolve(action(el.dataset.action,el)).catch(e=>toast(e.message,true));});
document.addEventListener('submit',event=>{if(!event.target.matches('form'))return;event.preventDefault();submit(event.target);});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='year-select'){const year=Number(el.value);await api('/api/settings',{active_year:year});app.year=year;app.month='';render();}if(el.id==='kind-filter'){app.kind=el.value;render();}if(el.id==='month-filter'){app.month=el.value;render();}if(el.id==='task-filter'){app.taskFilter=el.value;render();}if(el.id==='document-file'){app.pendingFile=el.files[0]||null;const label=$('#file-label');if(label)label.textContent=app.pendingFile?.name||'Keine Datei ausgewählt';if(!$('#f-title').value&&app.pendingFile)$('#f-title').value=app.pendingFile.name;}if(el.id==='transaction-receipt-file'){app.transactionReceiptFile=el.files[0]||null;const form=el.closest('form');if(form)form._receiptFile=app.transactionReceiptFile;const label=$('#transaction-receipt-label');if(label)label.textContent=app.transactionReceiptFile?`${app.transactionReceiptFile.name} · wird mit der Buchung gespeichert`:'Originalrechnung direkt mit dieser Buchung speichern.';}}catch(e){toast(e.message,true);}});
document.addEventListener('input',event=>{if(event.target.id==='search'){const caret=event.target.selectionStart;app.search=event.target.value;render();$('#search').focus();$('#search').setSelectionRange(caret,caret);}});
$('#modal').addEventListener('cancel',()=>{clearTimeout(app.poll);app.pendingFile=null;app.analysisDoc=null;});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(navItems.some(n=>n[0]===view)&&view!==app.view)navigate(view);});
async function start(){try{app.data=await api('/api/state');app.year=Number(app.data.settings.active_year)||2025;const view=location.hash.slice(1);if(navItems.some(n=>n[0]===view))app.view=view;render();}catch(e){$('#main').innerHTML=`<section class="error-screen"><h2>Dein Arbeitsplatz ist gerade nicht erreichbar.</h2><p>${esc(e.message)}</p><p>Bitte das lokale Programm starten und diese Seite neu laden.</p></section>`;}}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_document_capture',title:'Dokumenterfassung öffnen',description:'Öffnet das Eingabeformular. Speichert oder übermittelt keine Daten.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Leeres Objekt erwartet.');if(!app.data)throw new Error('Anwendung noch nicht bereit.');documentForm();return {opened:true,saved:false};}})).catch(()=>{});}catch{/* Unsupported experimental interface does not affect the application. */}}
